package mailjob

import (
	"encoding/base64"
	"encoding/json"
	"os"
	"testing"
)

// fixture is one case out of app/mail_queue/job.py's own MailJob.to_json,
// generated by scripts/python_job_bytes.py. The inputs are kept beside the
// expected text so the comparison rebuilds the same job rather than trusting
// that two hand-written literals say the same thing.
type fixture struct {
	Name    string `json:"name"`
	Message struct {
		To             string `json:"to"`
		Subject        string `json:"subject"`
		TextBody       string `json:"text_body"`
		HTMLBody       string `json:"html_body"`
		Sender         string `json:"sender"`
		ReplyTo        string `json:"reply_to"`
		IdempotencyKey string `json:"idempotency_key"`
		Attachments    []struct {
			Filename      string `json:"filename"`
			ContentBase64 string `json:"content_base64"`
			ContentType   string `json:"content_type"`
		} `json:"attachments"`
	} `json:"message"`
	Job struct {
		Kind       string   `json:"kind"`
		Ref        string   `json:"ref"`
		NotAfter   *float64 `json:"not_after"`
		Attempt    int      `json:"attempt"`
		ID         string   `json:"id"`
		EnqueuedAt float64  `json:"enqueued_at"`
	} `json:"job"`
	Expected string `json:"expected"`
}

func loadFixtures(t *testing.T) []fixture {
	t.Helper()
	raw, err := os.ReadFile("testdata/python_job_bytes.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixtures []fixture
	if err := json.Unmarshal(raw, &fixtures); err != nil {
		t.Fatal(err)
	}
	if len(fixtures) == 0 {
		t.Fatal("no fixtures")
	}
	return fixtures
}

func (f fixture) job(t *testing.T) Job {
	t.Helper()
	var attachments []Attachment
	for _, a := range f.Message.Attachments {
		content, err := base64.StdEncoding.DecodeString(a.ContentBase64)
		if err != nil {
			t.Fatal(err)
		}
		attachments = append(attachments, Attachment{
			Filename:    a.Filename,
			Content:     content,
			ContentType: a.ContentType,
		})
	}
	return Job{
		Message: Message{
			To:             f.Message.To,
			Subject:        f.Message.Subject,
			TextBody:       f.Message.TextBody,
			Sender:         f.Message.Sender,
			ReplyTo:        f.Message.ReplyTo,
			HTMLBody:       f.Message.HTMLBody,
			Attachments:    attachments,
			IdempotencyKey: f.Message.IdempotencyKey,
		},
		ID:         f.Job.ID,
		Kind:       f.Job.Kind,
		Ref:        f.Job.Ref,
		NotAfter:   f.Job.NotAfter,
		Attempt:    f.Job.Attempt,
		EnqueuedAt: f.Job.EnqueuedAt,
	}
}

func TestEncodeWritesTheBytesPythonWrote(t *testing.T) {
	for _, f := range loadFixtures(t) {
		t.Run(f.Name, func(t *testing.T) {
			got, err := f.job(t).Encode()
			if err != nil {
				t.Fatal(err)
			}
			if got != f.Expected {
				t.Errorf("not the bytes Python wrote\n go: %s\n py: %s", got, f.Expected)
			}
		})
	}
}

func TestDecodeReadsBackWhatPythonWrote(t *testing.T) {
	for _, f := range loadFixtures(t) {
		t.Run(f.Name, func(t *testing.T) {
			job, err := Decode(f.Expected)
			if err != nil {
				t.Fatal(err)
			}
			again, err := job.Encode()
			if err != nil {
				t.Fatal(err)
			}
			if again != f.Expected {
				t.Errorf("a round trip through the queue changed the entry\n got: %s\n was: %s", again, f.Expected)
			}
		})
	}
}
